import{D as d}from"./chunks/donate.3a95be8c.js";import{o,c,O as t,X as e}from"./chunks/framework.7fab6bae.js";import"./chunks/wcpay.d0e1a780.js";const a=e('<h1 id="紫微斗数宫位系统" tabindex="-1">紫微斗数の宮位体系 <a class="header-anchor" href="#紫微斗数宫位系统" aria-label="Permalink to &quot;紫微斗数の宮位体系  {#紫微斗数宫位系统}&quot;">​</a></h1><h2 id="前言" tabindex="-1">はじめに <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;はじめに  {#前言}&quot;">​</a></h2><p>宮は<code>垣</code>とも呼ばれ、紫微斗数の命盤で地支に従って周囲に並ぶ十二の区画を指します。<code>宮</code>と<code>位置</code>は異なる概念です。<code>宮</code>は固定された名称、<code>位置</code>は基準となる宮から見た相対的な位置です。例えば、あなたの<code>お父さん</code>と<code>おじいちゃん</code>は、あなたを基準とした<code>絶対的な呼称</code>です。父はあなたの<code>父母</code>宮に当たります。祖父はあなたの<code>福德</code>宮に当たると同時に、<code>父母</code>宮から見た<code>父母の位置</code>にも当たります。</p><blockquote><p><em>このシリーズの記事はオリジナルです。転載の際は出典を明記してください。</em></p></blockquote>',4),r=e('<p>紫微斗数の十二宮は、<a href="./astrolabe.html">命盤</a>上に次の順序で反時計回りに並びます。</p><table class="astrolabe"><tr><td>巳<code>田宅</code></td><td>午<code>官祿</code></td><td>未<code>僕役</code></td><td>申<code>遷移</code></td></tr><tr><td>辰<code>福德</code></td><td class="center-palace" rowspan="2" colspan="2">中宮</td><td>酉<code>疾厄</code></td></tr><tr><td>卯<code>父母</code></td><td>戌<code>財帛</code></td></tr><tr><td>寅<code>命宮</code></td><td>丑<code>兄弟</code></td><td>子<code>夫妻</code></td><td>亥<code>子女</code></td></tr></table><p>通常、命宮を除く十一宮では、表示名から<code>宮</code>の字を省きます。上の図には<code>宮名</code>と<code>地支</code>が示されています。地支の位置は固定されていますが、各位置に置かれる<code>宮名</code>は人によって異なります。そのため呼び方も二通りあります。<code>地支</code> + <code>宮</code>という呼び方、例えば<code>卯の宮</code>や<code>戌の宮</code>は、誰の命盤でも同じ位置を指します。一方、<code>宮名</code>で呼ぶと、その位置は命盤ごとに変わります。ある人の<code>財帛</code>宮が<code>辰の宮</code>にあり、別の人の<code>財帛</code>宮が<code>申の宮</code>にある、といった具合です。この二つの呼び方に対応して、分類法も二通りあります。その前に、まず十二宮の役割を学びましょう。</p><div class="tip custom-block"><p class="custom-block-title">ヒント</p><p>この記事で説明する宮は、<code>本命盤</code>を基準としています。本命盤が示すのは<code>態度</code>や<code>価値観</code>です。自分と同じ考えをよいと感じ、異なる考えを悪いと感じがちですが、その評価は相対的なものです。そのため、<code>本命盤</code>だけで特定の時期の吉凶を判断することはできません。ある時期にある宮がどのように作用するかを見るには、<code>運限盤</code>を参照します。詳しくは<a href="./horoscope.html">運限</a>で説明します。</p></div><h2 id="命宫" tabindex="-1"><code>命宮</code> <a class="header-anchor" href="#命宫" aria-label="Permalink to &quot;`命宮`  {#命宫}&quot;">​</a></h2><p>命宮はゲームの職業にたとえられ、本人の基本的な性格傾向を示します。ただし性格は立体的なので、命宮が表すのはあらゆる行動ではなく<code>本質</code>です。<code>性格が運命を決める</code>という言葉がありますが、筆者は性格よりも<code>認識</code>が重要だと考えます。同じ性格のタイプでも、理解の違いによって同じ出来事への考え方は変わるからです。昔ながらの<code>よい</code>と<code>悪い</code>、<code>吉</code>と<code>凶</code>という区分だけで命盤全体を決めつけるべきではありません。命宮は内在する特質を示しますが、他人が最初に接する性格は、多くの場合<a href="#迁移宫"><code>遷移</code></a>から見えるものです。</p><h2 id="兄弟宫" tabindex="-1"><code>兄弟</code> <a class="header-anchor" href="#兄弟宫" aria-label="Permalink to &quot;`兄弟`  {#兄弟宫}&quot;">​</a></h2><p>兄弟宮は主に兄弟姉妹との関係を示します。<code>父</code>と<code>母</code>を区別して見る場合には、<code>母</code>との関係も読み取ります。なぜ母親に関わるのでしょうか。<a href="#前言">はじめに</a>で説明した<code>宮</code>と<code>位置</code>の違いによるものです。本人の<code>兄弟</code>宮は、<code>父母</code>宮を基準にすると、その<code>夫妻の位置</code>にも当たります。この見方に慣れると、ほかの関係も導けます。伝統的な解釈で財運を見る際に<code>兄弟</code>宮も参照するのは、<code>財帛</code>宮から見た<code>田宅の位置</code>であり、流動資金の状態を示すためです。ただし、こうした関係を何重にもたどると混乱しやすくなります。まず兄弟姉妹との関係という基本の役割を理解してから、別の情報を掘り下げましょう。</p><h2 id="夫妻宫" tabindex="-1"><code>夫妻</code> <a class="header-anchor" href="#夫妻宫" aria-label="Permalink to &quot;`夫妻`  {#夫妻宫}&quot;">​</a></h2><p>夫妻宮は<code>恋愛や感情</code>を表し、相手の選び方や関係への姿勢を示します。命宮の<code>三方四正</code>には含まれませんが、恋愛や結婚が人生全体に影響する人は少なくありません。だからこそ、一つの宮だけがよいことより十二宮の均衡が重要です。どんな人にひかれるのか分からないときは、命盤を参考にできます。<code>相性を見る命盤の比較</code>とは、双方の命宮と夫妻宮を比較して、価値観や関係への姿勢が合うかを見ることです。夫妻宮を<code>恋愛の縁</code>の宮と考える人もいますが、<code>恋愛の縁</code>を主に表すのは<code>子女</code>宮です。</p><h2 id="子女宫" tabindex="-1"><code>子女</code> <a class="header-anchor" href="#子女宫" aria-label="Permalink to &quot;`子女`  {#子女宫}&quot;">​</a></h2><p>夫妻宮の説明で、子女宮は<code>恋愛の縁</code>の宮だと述べました。子どもの誕生につながる親密な関係から、恋愛や異性との縁へと意味を広げた解釈です。子女宮は<code>子女</code>と<code>恋愛の縁</code>のほか、<code>共同事業の相手</code>との関係も示します。<code>子女</code>宮が<code>官祿</code>宮から見た<code>僕役の位置</code>に当たり、つまり<code>仕事上の仲間</code>を表すためです。</p><h2 id="财帛宫" tabindex="-1"><code>財帛</code> <a class="header-anchor" href="#财帛宫" aria-label="Permalink to &quot;`財帛`  {#财帛宫}&quot;">​</a></h2><p>財帛宮がよければ金運もよいと思いがちですが、主に示すのはお金への態度、管理の考え方、物質的な欲求です。<code>生活を支える糧</code>に当たります。財帛宮が目立つ人は、同じ生活水準を保つためにより多くの資源を必要とする場合があります。その欲求を満たすため、お金の管理や稼ぐ機会に敏感になりやすいのです。<code>使うことを知る人は稼ぐことにも敏感になる</code>という言葉は、こうした人を指します。実際の財産の蓄積は<a href="#田宅宫"><code>田宅</code></a>で見ます。</p><h2 id="疾厄宫" tabindex="-1"><code>疾厄</code> <a class="header-anchor" href="#疾厄宫" aria-label="Permalink to &quot;`疾厄`  {#疾厄宫}&quot;">​</a></h2><p>疾厄宮は、命盤の本人の<code>身体</code>、つまり体質に関わる宮です。命盤作成ソフトでは<code>健康宮</code>と表示されることもありますが、それだけでは意味を十分に表せません。健康でも身体に負担がかかっている人がいる一方、病気でも手厚い待遇を受ける人がいるからです。<code>疾厄</code>には<code>病気</code>だけでなく、<code>身体的な負担</code>という意味もあります。<code>身体的な負担</code>という言葉を怖がる必要はありません。好きで取り組む<code>エクストリームスポーツ</code>も、身体にとっては<code>身体的な負担</code>でしょう。週に六、七日、ほとんど休みなく長時間働いたり、風雨や日差しにさらされて働いたりすることも<code>身体的な負担</code>です。この宮は身体への向き合い方も示し、運動を続けて体形を管理できる人と太りやすい人の違いにも、読み解く手がかりを与えます。</p><div class="warning custom-block"><p class="custom-block-title">注記</p><p>体調が悪いときは早めに受診してください。疾厄宮が<code>強い</code>からといって、身体を酷使してはいけません。</p></div><h2 id="迁移宫" tabindex="-1"><code>遷移</code> <a class="header-anchor" href="#迁移宫" aria-label="Permalink to &quot;`遷移`  {#迁移宫}&quot;">​</a></h2><p>遷移宮は命盤への<code>入り口</code>にたとえられます。人は自分を守るために外向きの姿を作り、<code>遷移</code>はその<code>自分を守る外向きの姿</code>や<code>自分の見せ方</code>を示します。「初めて会ったときは違った」という言葉は、長くつきあううちに<code>遷移</code>を通して<code>命宮</code>、さらに<code>福德</code>の特質が見えてくることで生まれます。遷移宮が強い人は自分の見せ方や対外的な人物像を作るのが上手で、初対面の印象もよくなりがちです。反対に、<code>人づきあいが苦手</code>、<code>身なりに無頓着</code>、あるいは<code>親しみやすさ</code>の低さが表れることもあります。他人の目をあまり気にしない気取らない人は、決めつけられたり距離を置かれたりしやすい面があります。</p><h2 id="仆役宫" tabindex="-1"><code>僕役</code> <a class="header-anchor" href="#仆役宫" aria-label="Permalink to &quot;`僕役`  {#仆役宫}&quot;">​</a></h2><p>僕役宮は<code>交友宮</code>とも呼ばれ、本人の<code>交友関係</code>や<code>友人選びの考え方</code>を示します。どんな友人を好み、どう選ぶのか、周囲に有力な人が多いのか、それとも飲食や遊びを共にするだけの人が多いのかを、主に<code>僕役</code>宮から読み取ります。この宮は比較的注目されません。仕事、恋愛、お金、親、子ども、健康はよく質問されますが、友人について尋ねる人は少ないのです。友人には選択の余地が大きく、この宮も特定の一人を指すわけではないためでしょう。ただし、<code>僕役</code>宮は<code>意思疎通</code>にも関わります。詳しくは<a href="#按宫名分类">宮名による分類</a>の<code>兄弟宮・僕役宮のライン</code>で説明します。</p><h2 id="官禄宫" tabindex="-1"><code>官祿</code> <a class="header-anchor" href="#官禄宫" aria-label="Permalink to &quot;`官祿`  {#官禄宫}&quot;">​</a></h2><p>官禄宮は<code>事業宮</code>とも呼ばれ、本人の<code>物事に取り組む姿勢</code>や仕事への姿勢を示します。将来の職業について考えがまとまらないときは、方向を探り、希望する仕事に必要な技能を補うための参考になります。まだ就職していない人、専業で家庭を支える人、パートナーに経済的に頼っている人にも関係するのでしょうか。関係します。この宮は<code>物事への向き合い方</code>を示すため、収入を伴う仕事の有無は問いません。学生には<code>勉強</code>、家庭を支える人には<code>家族の世話</code>が日々の仕事です。パートナーの支援で暮らす人には、その支援を安定して維持することが日々の関心事になります。</p><h2 id="田宅宫" tabindex="-1"><code>田宅</code> <a class="header-anchor" href="#田宅宫" aria-label="Permalink to &quot;`田宅`  {#田宅宫}&quot;">​</a></h2><p>田宅宮は<code>保有と蓄積</code>を示します。<code>不動産</code>だけでなく、<code>家族</code>との関係も表します。伝統的な解釈では<code>家庭の平穏</code>が重視され、この宮から人生の吉凶を見ました。和やかな家庭は大きな支えになりますから、家庭での状況が特に難しく表れる場合には、一人で暮らすことも考えられます。<a href="#财帛宫"><code>財帛</code>宮</a>の説明の通り、田宅宮は財産の蓄積も示します。<code>財産を蓄える場所</code>に当たるためです。財帛宮が強く田宅宮が損なわれている場合、よく稼ぐ一方でよく使う人かもしれません。反対に財帛宮が弱くても田宅宮が強ければ、収支を整えて貯蓄を好む人とも読めます。これは<code>よい</code>と<code>悪い</code>の違いではなく、消費や資産の保有に対する考え方の違いです。</p><h2 id="福德宫" tabindex="-1"><code>福德</code> <a class="header-anchor" href="#福德宫" aria-label="Permalink to &quot;`福德`  {#福德宫}&quot;">​</a></h2><p>遷移宮は外向きの姿を表し、ゲームキャラクターの<code>外見用スキン</code>にたとえられます。命宮は本来の性質で、<code>初期属性ポイント</code>のように、<code>筋力型</code>、<code>知力型</code>、<code>敏捷型</code>といったタイプを示します。疾厄宮は身体の強弱で、物理耐性に当たります。<code>福德</code>宮は<code>考え</code>を表します。解釈者が<code>内面を鍛える</code>と勧めるときは、外の状況や自分の不遇に振り回されない心の強さと、感情の安定を育てることを意味します。それによって、外からの刺激に衝動的に反応したり、判断を誤ったりしにくくなります。他の宮がしばしば<code>潜在意識</code>の反応を表すのに対し、<code>福德</code>宮は考えた上での反応に関わります。内面を安定させるほど、困難や失敗に対応する余地が広がります。</p><h2 id="父母宫" tabindex="-1"><code>父母</code> <a class="header-anchor" href="#父母宫" aria-label="Permalink to &quot;`父母`  {#父母宫}&quot;">​</a></h2><p>この見方では、父母宮は命宮が表す本人より<code>先に</code>生まれた世代、つまり自分では選べない親との関係を表す宮です。親を示し、多くの場合は<code>父</code>を中心に見ます。<a href="#兄弟宫"><code>兄弟</code>宮</a>で説明した通り、<code>母</code>との関係は<code>兄弟</code>宮で読み取ります。父母宮は<code>生まれたときからの支え</code>を表します。本人を木にたとえるなら、苗木に養分を与える土です。豊かな土壌で十分に支えられる木もあれば、乏しい条件で育つ木もあります。恵まれた家庭に生まれ、最初から有利な人生を送りたいと思う人は多いでしょうが、誰もがそうとは限りません。紫微斗数は命盤全体の均衡を重視します。父母宮が突出すると他の領域は相対的に弱くなり、親の庇護を離れてから、より大きな困難に直面することがあります。</p><hr><div class="tip custom-block"><p class="custom-block-title">ヒント</p><p>紫微斗数の<code>先天盤</code>には、本来よい悪いという区別があるのではなく、性質の違いがあります。人は集団で暮らし、協力するため、さまざまな能力や性格が必要です。他人が主観的に命盤をよい悪いと評価しても、自分の心を左右されないようにしましょう。基礎を自分で学ぶことは、より多面的で客観的な自己理解に役立ちます。</p></div><h2 id="特殊宫位" tabindex="-1">特殊な宮 <a class="header-anchor" href="#特殊宫位" aria-label="Permalink to &quot;特殊な宮 {#特殊宫位}&quot;">​</a></h2><p>命盤の十二の区画に示された宮のほかに、紫微斗数には三つの隠れた宮があります。<code>身宮</code>、<code>暗合宮</code>、<code>来因</code>宮です。</p><h3 id="身宫" tabindex="-1"><code>身宮</code> <a class="header-anchor" href="#身宫" aria-label="Permalink to &quot;`身宮`  {#身宫}&quot;">​</a></h3><p>身宮は本人の性格の<code>変化の方向</code>を示し、<code>命宮</code>の特質にも影響します。命宮が<code>先天的な特徴</code>を表すのに対し、<code>身宮</code>は<code>獲得した特性</code>を表します。ゲームキャラクターの初期能力値にたとえると、例えば次のようになります。</p><table><thead><tr><th>能力値</th><th>初期値</th></tr></thead><tbody><tr><td>筋力</td><td>8</td></tr><tr><td>敏捷性</td><td>4</td></tr><tr><td>知力</td><td>5</td></tr></tbody></table><p>初期能力値はキャラクター作成時に決まっています。<code>身宮</code>は、その後の成長で得たポイントをどこに配分するかにたとえられます。<code>敏捷性</code>を伸ばす人も、<code>筋力</code>や<code>知力</code>を伸ばす人もいます。同じ<code>紫微</code>が命宮にある人でも、身宮の主星によって性格の発展方向は変わります。強引な暴君のようになることも、開明的な賢君のようになることもあります。<code>身宮</code>が入るのは次の六宮だけです。</p><ul><li><p>身宮が命宮にある場合</p><p>身宮と命宮が同じ宮にある人は、考えが固く、性格も安定している傾向があります。ゲームにたとえれば、<code>筋力</code>型のキャラクターが成長してからも<code>筋力</code>にポイントを振り続けるようなものです。そのため進む方向が特に重要です。揺るぎない姿勢は成功へ着実に進む力になりますが、方向が誤っていると、進路を変えようとしない頑固さにもなります。</p></li><li><p>身宮が遷移宮にある場合</p><p>身宮が遷移宮にある人は、他人の目や自分の<code>外に見せる姿</code>を強く意識します。ゲームにたとえれば、キャラクターの<code>外見用スキン</code>を重視するようなものです。外で活動することも好みます。周囲に尊敬される対外的な人物像を作ることが、一生の目標になりやすく、外からの評価を求めます。適切な方向で努力すれば<code>名を上げる</code>ことにつながりますが、不適切な手段を取れば、かえって評判を損なうことがあります。</p></li><li><p>身宮が夫妻宮にある場合</p><p>身宮が夫妻宮にある人は、感情や関係をより重視する傾向があります。良い関係を築くことが、一生をかけて取り組む <code>人生の課題</code> になることもあります。感情は、人生の中でも特に複雑なものです。執着が強すぎると <code>情にとらわれる</code> 状態になりやすく、<code>心理的な操作</code> も受けやすくなります。深く傷ついた結果、強い愛情を望みながらも <code>恋愛</code> から距離を置く人がいるのは、本能的な <code>自己防衛</code> とも言えます。一方、相手との関係に満足していれば、<code>愛があれば物質的な不足も受け入れられる</code> と感じ、ほかのものを手放してでも関係を大切にすることがあります。</p></li><li><p>身宮が官祿宮にある場合</p><p>身宮が官祿宮にある人は、自分の<code>行動</code>や、課題を遂行する<code>方法</code>を特に重視します。そのため、<code>仕事</code>や<code>キャリア</code>への関心が強くなります。<code>キャリア</code>が大きな目標なので、<code>仕事中毒</code>になりやすく、一心に仕事へ打ち込んで成果を上げられます。ただし、能力が足りなかったり努力の方向が誤っていたりすると、仕事でのつまずきによる打撃も大きくなりがちです。</p></li><li><p>身宮が財帛宮にある場合</p><p>身宮が財帛宮にある人は物質的な欲求が強く、財産に安心を見いだしやすいため、<code>お金への執着</code>が生じやすくなります。お金は誰もが好むものですが、この配置では特に重視されます。求めるとしても正当な方法で得ることが大切です。恋愛、仕事、財産のいずれも、過度な執着はよいとはいえません。とりわけお金や物は目に見えて手に取れるため、支配し、所有し、奪い合いたいという気持ちを刺激しやすいのです。</p></li><li><p>身宮が福德宮にある場合</p><p>身宮が福德宮にある人は、<code>精神</code>の楽しみや満足を重視します。<a href="#福德宫"><code>福德</code>宮</a>の説明の通り、この宮は内面や思考を表します。身宮がここにあると、内面的な追求や楽しみへの関心が強まります。その分<code>依存しやすさ</code>も高まり、好きな人や活動、物に頼りやすくなります。他の身宮配置で述べた<code>向かう方向</code>の問題と同様、望ましくない方向へ進むと、特に対処しにくい問題が生じることがあります。そのため、自分の心理状態をより大切に見守る必要があります。</p></li></ul><h3 id="暗合宫" tabindex="-1"><code>暗合宮</code> <a class="header-anchor" href="#暗合宫" aria-label="Permalink to &quot;`暗合宮`  {#暗合宫}&quot;">​</a></h3><p>暗合宮は、十二地支の<a href="./basis.html#地支六合"><code>地支六合</code></a>から導かれます。組み合わせを暗記しなくても、命盤を中央で縦に分ければ、左右で鏡映の位置にある宮が互いの暗合宮だと分かります。</p><table class="astrolabe"><tr><td>巳<code>申と暗合</code></td><td style="border-right-width:3px;">午<code>未と暗合</code></td><td>未<code>午と暗合</code></td><td>申<code>巳と暗合</code></td></tr><tr><td>辰<code>酉と暗合</code></td><td class="center-palace" rowspan="2" style="border-right-width:3px;"></td><td class="center-palace" rowspan="2"></td><td>酉<code>辰と暗合</code></td></tr><tr><td>卯<code>戌と暗合</code></td><td>戌<code>卯と暗合</code></td></tr><tr><td>寅<code>亥と暗合</code></td><td style="border-right-width:3px;">丑<code>子と暗合</code></td><td>子<code>丑と暗合</code></td><td>亥<code>寅と暗合</code></td></tr></table><p><code>暗合</code>は、<code>表に出ないところ</code>で働く関係を意味します。<code>明科暗禄</code>格は、<code>命宮</code>に化<code>科</code>があり、その<code>暗合宮</code>に化<code>祿</code>または<code>祿存</code>がある配置です。表には<code>名声</code>が現れ、見えないところでは<code>富</code>も得る、という組み合わせです。筆者はこれを、中国の伝統的な価値観や一般的な理想像に合うものと説明しています。そのため<code>明科暗禄</code>格は高く評価されます。格局については<a href="./pattern.html#紫微斗数格局">格局</a>で説明します。</p><h3 id="来因宫" tabindex="-1"><code>来因</code> <a class="header-anchor" href="#来因宫" aria-label="Permalink to &quot;`来因`  {#来因宫}&quot;">​</a></h3><p>来因宮は、その名の通り<code>この世に来た理由</code>という問いを見る宮です。実際の解釈で使う機会は比較的少ないため、参考程度に、まずはこうした概念があると知っておけば十分です。</p><ul><li><p>来因宮は何に使いますか？</p><p>来因宮は、働く分野を選ぶ際の参考になります。<code>子女</code>宮にあれば、<code>親子</code>、<code>社交</code>、<code>合併と買収</code>に関わる仕事を考えられます。<code>財帛</code>宮なら、<code>金融</code>、<code>有価証券</code>、<code>投資</code>などが例です。ただし、検討の手がかりにすぎず、職業を決める基準ではありません。</p></li><li><p>来因宮はどう見つけますか？</p><p>生まれた年の<code>天干</code>と宮干が同じ宮を探します。例えば<code>癸卯</code>年生まれなら、宮干が<code>癸</code>の宮が来因宮です。ただし<code>子</code>と<code>丑</code>の位置は除外し、これを<code>天地を来因としない</code>と呼びます。<a href="./basis.html#术语解释">用語解説</a>の通り、<code>子の宮</code>は天、<code>丑の宮</code>は地に当たります。該当する天干がこの二つの位置の宮干と一致する場合には、同じ宮干を持つ<code>寅の宮</code>または<code>卯の宮</code>を、それぞれ代わりに選びます。</p></li></ul><h2 id="宫位的分类" tabindex="-1">宮の分類 <a class="header-anchor" href="#宫位的分类" aria-label="Permalink to &quot;宮の分類 {#宫位的分类}&quot;">​</a></h2><h3 id="按地支分类" tabindex="-1">地支による分類 <a class="header-anchor" href="#按地支分类" aria-label="Permalink to &quot;地支による分類 {#按地支分类}&quot;">​</a></h3><p>各宮の位置には固有の性質があり、本人の特質に傾向を加えます。この分類は五行に基づきます。この体系では、<code>⛰️土</code>はあらゆる物の<code>最終的な帰着点</code>であり、<code>🪙金</code>、<code>🪵木</code>、<code>🌊水</code>、<code>🔥火</code>は最終的に<code>⛰️土</code>へ帰ります。この考え方から、宮の位置を次の三種類に分けます。</p><h4 id="四生地" tabindex="-1">四生地 <a class="header-anchor" href="#四生地" aria-label="Permalink to &quot;四生地  {#四生地}&quot;">​</a></h4><p><code>四馬地</code>とも呼ばれます。<code>天馬</code>がこの四つの位置にしか入らないためです。<code>⛰️土</code>を除く四つの五行が<code>誕生</code>する位置に当たります。元気で好奇心旺盛な子どものように、<code>行動力</code>や<code>探検したいという欲求</code>を加えますが、安定性が乏しく<code>移り気</code>も生じやすくなります。該当する位置は次の通りです。</p><ul><li><p>寅</p><p><code>🪵木</code>が生まれる位置</p></li><li><p>申</p><p><code>🪙金</code>が生まれる位置</p></li><li><p>巳</p><p><code>🔥火</code>が生まれる位置</p></li><li><p>亥</p><p><code>🌊水</code>が生まれる位置</p></li></ul><p>命盤では、次の四隅の宮に当たります。</p><table class="astrolabe"><tr><td>巳<code>四生地</code></td><td style="background:transparent;">午</td><td style="background:transparent;">未</td><td>申<code>四生地</code></td></tr><tr><td style="background:transparent;">辰</td><td style="background:transparent;" class="center-palace" rowspan="2" colspan="2"></td><td style="background:transparent;">酉</td></tr><tr><td style="background:transparent;">卯</td><td style="background:transparent;">戌</td></tr><tr><td>寅<code>四生地</code></td><td style="background:transparent;">丑</td><td style="background:transparent;">子</td><td>亥<code>四生地</code></td></tr></table><h4 id="四旺地" tabindex="-1">四旺地 <a class="header-anchor" href="#四旺地" aria-label="Permalink to &quot;四旺地  {#四旺地}&quot;">​</a></h4><p><code>四敗地</code>とも呼ばれます。この四つの位置では<code>🌊水</code>、<code>🪵木</code>、<code>🔥火</code>、<code>🪙金</code>が盛んな段階にあり、意欲や満足感が強く、何でもできるという気持ちになりやすいとされます。そのため<code>自信</code>や<code>支配欲</code>を加えますが、<code>衝動性</code>も強まります。自信が過剰になると能力を超えた行動をして大きく失敗することがあるため、<code>四敗地</code>という別名もあります。該当する位置は次の通りです。</p><ul><li><p>子</p><p><code>🌊水</code>が最も盛んになる位置</p></li><li><p>午</p><p><code>🔥火</code>が最も盛んになる位置</p></li><li><p>酉</p><p><code>🪙金</code>が最も盛んになる位置</p></li><li><p>卯</p><p><code>🪵木</code>が最も盛んになる位置</p></li></ul><p>命盤では、次の四つの宮に当たります。</p><table class="astrolabe"><tr><td style="background:transparent;">巳</td><td>午<code>四旺地</code></td><td style="background:transparent;">未</td><td style="background:transparent;">申</td></tr><tr><td style="background:transparent;">辰</td><td style="background:transparent;" class="center-palace" rowspan="2" colspan="2"></td><td>酉<code>四旺地</code></td></tr><tr><td>卯<code>四旺地</code></td><td style="background:transparent;">戌</td></tr><tr><td style="background:transparent;">寅</td><td style="background:transparent;">丑</td><td>子<code>四旺地</code></td><td style="background:transparent;">亥</td></tr></table><h4 id="四墓库" tabindex="-1">四墓庫 <a class="header-anchor" href="#四墓库" aria-label="Permalink to &quot;四墓庫  {#四墓库}&quot;">​</a></h4><p>幼いころの<code>好奇心</code>、盛んな時期の<code>自信</code>を経て、中年の<code>落ち着き</code>に至ったような位置です。この四つの位置は<code>堅実さ</code>と<code>集中力</code>を加える一方、<code>活力</code>や<code>意欲</code>を少し減らします。<code>祿存</code>はここに入らず、<code>祿存遇土不進</code>と表現されます。この星については<a href="./minor-star.html#禄存">禄存</a>で説明します。<code>富</code>を象徴することから、筆者は財産には<code>流れ</code>が必要だという意味を読み取り、古人の知恵に感心しています。四つの蓄積の位置は次の通りです。</p><ul><li><p>辰</p><p><code>🌊水</code>を蓄える位置</p></li><li><p>戌</p><p><code>🔥火</code>を蓄える位置</p></li><li><p>丑</p><p><code>🪙金</code>を蓄える位置</p></li><li><p>未</p><p><code>🪵木</code>を蓄える位置</p></li></ul><p>命盤では、次の四つの宮に当たります。</p><table class="astrolabe"><tr><td style="background:transparent;">巳</td><td style="background:transparent;">午</td><td>未<code>四墓庫</code></td><td style="background:transparent;">申</td></tr><tr><td>辰<code>四墓庫</code></td><td style="background:transparent;" class="center-palace" rowspan="2" colspan="2"></td><td style="background:transparent;">酉</td></tr><tr><td style="background:transparent;">卯</td><td>戌<code>四墓庫</code></td></tr><tr><td style="background:transparent;">寅</td><td>丑<code>四墓庫</code></td><td style="background:transparent;">子</td><td style="background:transparent;">亥</td></tr></table><h3 id="按宫名分类" tabindex="-1">宮名による分類 <a class="header-anchor" href="#按宫名分类" aria-label="Permalink to &quot;宮名による分類   {#按宫名分类}&quot;">​</a></h3><p>地支による分類は、本人の性質に加わる傾向を示します。一方、宮名による分類は<code>生活上の事柄</code>に関わります。十二宮は<a href="./basis.html#地支六冲"><code>地支六冲</code></a>の関係によって六つのラインに分かれます。<code>互いに冲</code>する二つの宮は切り離せない関係にあり、互いに支え合うと同時に、折り合いをつけにくい対立も生じます。六つのラインは次の通りです。</p><ul><li><p>命宮・遷移宮のライン</p><p>このラインは<code>命宮</code>と<code>遷移</code>を結び、本人の<code>内面と外向きの姿</code>を表します。そのため、このラインに関わる宮は本人に直接影響します。</p></li><li><p>兄弟宮・僕役宮のライン</p><p>このラインは<code>兄弟</code>と<code>僕役</code>を結び、<code>人づきあい</code>を表します。人づきあいには意思疎通が必要なので、<code>意思疎通のライン</code>とも呼ばれます。また、人脈はその人が活動できる範囲を反映するため、<code>達成のライン</code>という別名もあります。</p></li><li><p>官祿宮・夫妻宮のライン</p><p>このラインは<code>官祿</code>と<code>夫妻</code>を結び、<code>キャリア</code>に関わります。パートナーの支えは仕事の助けになりますが、仕事への不満や反対が強いと働きにくくなります。仕事の状況も、パートナーとの関係での立場に影響します。両者の調整は簡単ではありません。仕事を重視しすぎると関係をおろそかにし、関係を重視しすぎると仕事で前進しにくくなり、仕事への意欲が低いと見られることもあります。この均衡をうまく保つことには、大きな意味があります。</p></li><li><p>子女宮・田宅宮のライン</p><p>このラインは<code>子女</code>と<code>田宅</code>を結び、<code>恋愛の縁のライン</code>とも呼ばれます。理由は<a href="#子女宫"><code>子女</code></a>の説明を参照してください。親子関係、家族関係、共同事業の相手との関係、異性との関係など、広い範囲に関わります。</p></li><li><p>財帛宮・福德宮のライン</p><p>このラインは<code>財帛</code>と<code>福德</code>を結び、主に消費やお金の管理に対する考え方を示します。</p></li><li><p>父母宮・疾厄宮のライン</p><p>このラインは<code>父母</code>と<code>疾厄</code>を結び、<code>文書のライン</code>とも呼ばれます。本人と親との関係を<code>契約的な結びつき</code>という観点から表すためです。</p></li></ul><div class="tip custom-block"><p class="custom-block-title">ヒント</p><p>宮の<code>別名</code>を覚えておくと、命盤の解釈に役立ちます。例えば、<code>夫妻</code>からの化忌が<code>兄弟宮・僕役宮のライン</code>を冲する場合、その別名である<code>意思疎通のライン</code>から、関係に<code>コミュニケーションの問題</code>がある可能性を読み取れます。</p></div><h2 id="三方四正" tabindex="-1">三方四正 <a class="header-anchor" href="#三方四正" aria-label="Permalink to &quot;三方四正  {#三方四正}&quot;">​</a></h2><p>三方四正は一つの宮ではなく、四つの宮の総称です。<code>対象の宮</code>、<code>対宮</code>（<code>対宮の位置</code>とも呼ぶ）、二つの<code>三合宮</code>（<code>三方の位置</code>とも呼ぶ）が含まれます。<code>三方の位置</code>と<code>対宮の位置</code>が対象の宮に強く影響するため、まとめて分析します。</p><ul><li><p>対象の宮</p><p><code>対象の宮</code>は、今分析している宮です。どの宮も分析対象になり得ます。</p></li><li><p>対宮</p><p><code>対象の宮</code>の地支と<a href="./basis.html#地支六冲"><code>六冲</code></a>を成す地支にある宮です。<code>対象の宮</code>の<code>向かい側</code>にあるため、<code>対宮</code>と呼びます。例えば、<code>寅の宮</code>の対宮は<code>申の宮</code>です。</p></li><li><p>三合宮</p><p>地支が<code>対象の宮</code>の地支と<a href="./basis.html#地支三合局"><code>地支三合局</code></a>を成す、残りの二つの宮です。例えば、<code>申の宮</code>の三合宮は<code>子の宮</code>と<code>辰の宮</code>です。</p><table class="astrolabe"><tr><td>巳<code>対象の宮</code></td><td style="background:transparent;">午</td><td style="background:transparent;">未</td><td style="background:transparent;">申</td></tr><tr><td style="background:transparent;">辰</td><td style="background:transparent;" class="center-palace" rowspan="2" colspan="2"></td><td>酉<code>三合の位置</code></td></tr><tr><td style="background:transparent;">卯</td><td style="background:transparent;">戌</td></tr><tr><td style="background:transparent;">寅</td><td>丑<code>三合の位置</code></td><td style="background:transparent;">子</td><td>亥<code>対宮の位置</code></td></tr></table></li></ul>',70),b=JSON.parse('{"title":"紫微斗数の十二宮：意味と関係","description":"紫微斗数の命盤を構成する十二宮と、それぞれの宮が表す人生の領域を紹介します。","frontmatter":{"title":"紫微斗数の十二宮：意味と関係","outline":"deep","description":"紫微斗数の命盤を構成する十二宮と、それぞれの宮が表す人生の領域を紹介します。","head":[["link",{"rel":"canonical","href":"https://iztro.com/ja_JP/learn/palace.html"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://iztro.com/learn/palace.html"}],["link",{"rel":"alternate","hreflang":"zh-TW","href":"https://iztro.com/zh_TW/learn/palace.html"}],["link",{"rel":"alternate","hreflang":"en-US","href":"https://iztro.com/en_US/learn/palace.html"}],["link",{"rel":"alternate","hreflang":"ko-KR","href":"https://iztro.com/ko_KR/learn/palace.html"}],["link",{"rel":"alternate","hreflang":"ja-JP","href":"https://iztro.com/ja_JP/learn/palace.html"}],["link",{"rel":"alternate","hreflang":"vi-VN","href":"https://iztro.com/vi_VN/learn/palace.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://iztro.com/learn/palace.html"}],["meta",{"name":"robots","content":"max-image-preview:large"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"紫微研习社"}],["meta",{"property":"og:title","content":"紫微斗数の十二宮：意味と関係 | 紫微研习社"}],["meta",{"property":"og:description","content":"紫微斗数の命盤を構成する十二宮と、それぞれの宮が表す人生の領域を紹介します。"}],["meta",{"property":"og:url","content":"https://iztro.com/ja_JP/learn/palace.html"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:locale:alternate","content":"zh_CN"}],["meta",{"property":"og:locale:alternate","content":"zh_TW"}],["meta",{"property":"og:locale:alternate","content":"en_US"}],["meta",{"property":"og:locale:alternate","content":"ko_KR"}],["meta",{"property":"og:locale:alternate","content":"vi_VN"}],["meta",{"property":"og:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"property":"og:image:width","content":"850"}],["meta",{"property":"og:image:height","content":"850"}],["meta",{"property":"og:image:alt","content":"紫微研习社"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"紫微斗数の十二宮：意味と関係 | 紫微研习社"}],["meta",{"name":"twitter:description","content":"紫微斗数の命盤を構成する十二宮と、それぞれの宮が表す人生の領域を紹介します。"}],["meta",{"name":"twitter:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"name":"twitter:image:alt","content":"紫微研习社"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://iztro.com/ja_JP/learn/palace.html#webpage\\",\\"url\\":\\"https://iztro.com/ja_JP/learn/palace.html\\",\\"name\\":\\"紫微斗数の十二宮：意味と関係 | 紫微研习社\\",\\"description\\":\\"紫微斗数の命盤を構成する十二宮と、それぞれの宮が表す人生の領域を紹介します。\\",\\"inLanguage\\":\\"ja-JP\\",\\"isPartOf\\":{\\"@id\\":\\"https://iztro.com/#website\\"},\\"breadcrumb\\":{\\"@id\\":\\"https://iztro.com/ja_JP/learn/palace.html#breadcrumb\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"@id\\":\\"https://iztro.com/ja_JP/learn/palace.html#breadcrumb\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"紫微研习社\\",\\"item\\":\\"https://iztro.com/ja_JP/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"紫微斗数の十二宮：意味と関係\\",\\"item\\":\\"https://iztro.com/ja_JP/learn/palace.html\\"}]}]}"]]},"headers":[],"relativePath":"ja_JP/learn/palace.md","filePath":"ja_JP/learn/palace.md"}'),l={name:"ja_JP/learn/palace.md"},u=Object.assign(l,{setup(p){return(n,i)=>(o(),c("div",null,[a,t(d),r]))}});export{b as __pageData,u as default};
